import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const headerPath = path.join(root, "userscript", "metadata.txt");
const packagePath = path.join(root, "package.json");
const srcDir = path.join(root, "userscript", "src");

export function buildUserscript() {
  const { version } = JSON.parse(fs.readFileSync(packagePath, "utf8"));
  const header = fs
    .readFileSync(headerPath, "utf8")
    .replace(/^\/\/ @version\s+.*$/m, `// @version      ${version}`)
    .trimEnd();
  const modules = fs
    .readdirSync(srcDir)
    .filter((name) => name.endsWith(".js"))
    .sort();

  if (modules.length === 0) {
    throw new Error("No source modules found in userscript/src/");
  }

  const body = modules
    .map((name) => {
      const filePath = path.join(srcDir, name);
      return `  // --- ${name} ---\n${fs.readFileSync(filePath, "utf8").trimEnd()}`;
    })
    .join("\n\n");

  const source = [
    header,
    "",
    "// Generated by `npm run build`. Edit userscript/src/ instead of this file.",
    "",
    "(function () {",
    '  "use strict";',
    "",
    body,
    "})();",
    ""
  ].join("\n");

  return { source, moduleCount: modules.length };
}
